/* Minimal hand-written replacement for the config.h that dav1d's meson build
 * normally generates. Only what the ported C kernels need: 8bpc only, no
 * logging. ARCH_* / HAVE_* defer to the harness platform config
 * (vbench_config.h, generated by the root CMake from the same detection the
 * rest of the harness uses); HAVE_ASM can additionally be forced to 1 by the
 * codec CMakeLists when the upstream asm lib is built for this arch (the
 * tmpl files then include the src/{arm,x86} asm decl headers and call the
 * arch init). On macOS the asm additionally needs the Mach-O symbol
 * underscore prefix and no .func directive. */
#ifndef VBENCH_KERNELS_DAV1D_CONFIG_H
#define VBENCH_KERNELS_DAV1D_CONFIG_H

#include "vbench_config.h"

#define CONFIG_8BPC 1
#define CONFIG_16BPC 0
#define CONFIG_LOG 0
#define CONFIG_ASM_DEBUG 0
#define TRIM_DSP_FUNCTIONS 0

#ifndef HAVE_ASM
#define HAVE_ASM 0
#endif

/* Mach-O asm specifics (symbol underscore prefix, no .func directive) */
#if SYS_MACOSX
#ifndef PREFIX
#define PREFIX
#endif
#ifndef HAVE_AS_FUNC
#define HAVE_AS_FUNC 0
#endif
#endif

#ifndef ARCH_AARCH64
#define ARCH_AARCH64 0
#endif
#ifndef ARCH_ARM
#define ARCH_ARM 0
#endif
#ifndef ARCH_X86
#define ARCH_X86 0
#endif
#ifndef ARCH_X86_64
#define ARCH_X86_64 0
#endif
#ifndef ARCH_X86_32
#define ARCH_X86_32 0
#endif
#ifndef ARCH_PPC64LE
#define ARCH_PPC64LE 0
#endif
#ifndef ARCH_RISCV
#define ARCH_RISCV 0
#endif
#ifndef ARCH_RV32
#define ARCH_RV32 0
#endif
#ifndef ARCH_RV64
#define ARCH_RV64 0
#endif
#ifndef ARCH_LOONGARCH
#define ARCH_LOONGARCH 0
#endif
#ifndef ARCH_LOONGARCH32
#define ARCH_LOONGARCH32 0
#endif
#ifndef ARCH_LOONGARCH64
#define ARCH_LOONGARCH64 0
#endif

#ifndef HAVE_AS_ARCH_DIRECTIVE
#define HAVE_AS_ARCH_DIRECTIVE 0
#endif
#ifndef HAVE_AS_FPU_DIRECTIVE
#define HAVE_AS_FPU_DIRECTIVE 0
#endif
#ifndef HAVE_AS_ARCH_LEVEL_DIRECTIVE
#define HAVE_AS_ARCH_LEVEL_DIRECTIVE 0
#endif

#endif /* VBENCH_KERNELS_DAV1D_CONFIG_H */
